result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/wizard-ui/src/Wizard.tsx", "content": "import { useState, type FormEvent } from "react";

export type WizardData = {
  email: string;
  password: string;
  displayName: string;
};

type WizardProps = {
  onComplete: (data: WizardData) => void;
};

const STEPS = ["account", "profile", "confirm"] as const;
type Step = (typeof STEPS)[number];

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validateAccount(data: WizardData): Partial<Record<keyof WizardData, string>> {
  const errors: Partial<Record<keyof WizardData, string>> = {};
  if (!data.email.trim()) {
    errors.email = "Email is required.";
  } else if (!emailPattern.test(data.email)) {
    errors.email = "Enter a valid email address.";
  }
  if (!data.password) {
    errors.password = "Password is required.";
  } else if (data.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }
  return errors;
}

function validateProfile(data: WizardData): Partial<Record<keyof WizardData, string>> {
  const errors: Partial<Record<keyof WizardData, string>> = {};
  if (!data.displayName.trim()) {
    errors.displayName = "Display name is required.";
  }
  return errors;
}

const VALIDATORS: Record<number, (d: WizardData) => Partial<Record<keyof WizardData, string>>> = {
  0: validateAccount,
  1: validateProfile,
};

export default function Wizard({ onComplete }: WizardProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [data, setData] = useState<WizardData>({
    email: "",
    password: "",
    displayName: "",
  });
  // Errors are only surfaced for the step the user is trying to leave.
  const [errors, setErrors] = useState<Partial<Record<keyof WizardData, string>>>({});

  function update<K extends keyof WizardData>(field: K, value: string) {
    setData((prev) => ({ ...prev, [field]: value }));
  }

  function handleNext(event: FormEvent) {
    event.preventDefault();
    const validate = VALIDATORS[stepIndex];
    if (!validate) return;
    const stepErrors = validate(data);
    if (Object.keys(stepErrors).length > 0) {
      setErrors(stepErrors);
      return;
    }
    setErrors({});
    setStepIndex((i) => Math.min(i + 1, STEPS.length - 1));
  }

  function handleBack() {
    setErrors({});
    setStepIndex((i) => Math.max(i - 1, 0));
  }

  function goTo(step: Step) {
    setErrors({});
    setStepIndex(STEPS.indexOf(step));
  }

  function handleSubmit(event: FormEvent) {
    event.preventDefault();
    onComplete({ ...data });
  }

  return (
    <div>
      <ol aria-label="Progress">
        {STEPS.map((step, index) => (
          <li key={step} aria-current={index === stepIndex ? "step" : undefined}>
            {step}
          </li>
        ))}
      </ol>

      <form onSubmit={handleSubmit} noValidate>
        {stepIndex === 0 && (
          <section aria-labelledby="account-heading">
            <h2 id="account-heading">Account</h2>
            <div>
              <label htmlFor="email">Email</label>
              <input
                id="email"
                type="email"
                value={data.email}
                onChange={(e) => update("email", e.target.value)}
                aria-invalid={errors.email ? true : undefined}
                aria-describedby={errors.email ? "email-error" : undefined}
              />
              {errors.email && (
                <p id="email-error" role="alert">
                  {errors.email}
                </p>
              )}
            </div>
            <div>
              <label htmlFor="password">Password</label>
              <input
                id="password"
                type="password"
                value={data.password}
                onChange={(e) => update("password", e.target.value)}
                aria-invalid={errors.password ? true : undefined}
                aria-describedby={errors.password ? "password-error" : undefined}
              />
              {errors.password && (
                <p id="password-error" role="alert">
                  {errors.password}
                </p>
              )}
            </div>
          </section>
        )}

        {stepIndex === 1 && (
          <section aria-labelledby="profile-heading">
            <h2 id="profile-heading">Profile</h2>
            <div>
              <label htmlFor="displayName">Display name</label>
              <input
                id="displayName"
                type="text"
                value={data.displayName}
                onChange={(e) => update("displayName", e.target.value)}
                aria-invalid={errors.displayName ? true : undefined}
                aria-describedby={errors.displayName ? "displayName-error" : undefined}
              />
              {errors.displayName && (
                <p id="displayName-error" role="alert">
                  {errors.displayName}
                </p>
              )}
            </div>
          </section>
        )}

        {stepIndex === 2 && (
          <section aria-labelledby="confirm-heading">
            <h2 id="confirm-heading">Confirm</h2>
            <dl>
              <dt>Email</dt>
              <dd>{data.email}</dd>
              <dt>Password</dt>
              <dd>••••••••</dd>
              <dt>Display name</dt>
              <dd>{data.displayName}</dd>
            </dl>
            <p>
              <a href="#account" onClick={(e) => { e.preventDefault(); goTo("account"); }}>
                Edit account
              </a>
            </p>
            <p>
              <a href="#profile" onClick={(e) => { e.preventDefault(); goTo("profile"); }}>
                Edit profile
              </a>
            </p>
          </section>
        )}

        {stepIndex > 0 && (
          <button type="button" onClick={handleBack}>
            Back
          </button>
        )}

        {stepIndex < STEPS.length - 1 ? (
          <button type="button" onClick={handleNext}>
            Next
          </button>
        ) : (
          <button type="submit">Submit</button>
        )}
      </form>
    </div>
  );
}
"})
