result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/wizard-ui/src/Wizard.test.tsx", "content": "import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import Wizard, { type WizardData } from "./Wizard";

async function fillAccount(user: ReturnType<typeof userEvent.setup>, email: string, password: string) {
  await user.type(screen.getByLabelText("Email"), email);
  await user.type(screen.getByLabelText("Password"), password);
  await user.click(screen.getByRole("button", { name: "Next" }));
}

describe("<Wizard />", () => {
  it("completes the full happy path and calls onComplete with the merged payload", async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    render(<Wizard onComplete={onComplete} />);

    // Step indicator marks "account" as current.
    expect(screen.getByText("account")).toHaveAttribute("aria-current", "step");

    await fillAccount(user, "ada@example.com", "s3cret-pass");

    // Now on profile step.
    expect(screen.getByRole("heading", { name: "Profile" })).toBeInTheDocument();
    expect(screen.getByText("profile")).toHaveAttribute("aria-current", "step");

    await user.type(screen.getByLabelText("Display name"), "Ada Lovelace");
    await user.click(screen.getByRole("button", { name: "Next" }));

    // Confirm step shows a read-only summary of everything entered.
    const summary = screen.getByRole("region", { name: "Confirm" });
    expect(within(summary).getByText("ada@example.com")).toBeInTheDocument();
    expect(within(summary).getByText("Ada Lovelace")).toBeInTheDocument();
    expect(screen.getByText("confirm")).toHaveAttribute("aria-current", "step");
    expect(screen.queryByLabelText("Email")).not.toBeInTheDocument();

    await user.click(screen.getByRole("button", { name: "Submit" }));

    expect(onComplete).toHaveBeenCalledTimes(1);
    expect(onComplete).toHaveBeenCalledWith<WizardData>({
      email: "ada@example.com",
      password: "s3cret-pass",
      displayName: "Ada Lovelace",
    });
  });

  it("blocks Next on step one until validation passes and shows inline errors", async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    render(<Wizard onComplete={onComplete} />);

    // Empty submit is blocked; we stay on account with inline errors.
    await user.click(screen.getByRole("button", { name: "Next" }));
    expect(screen.getByRole("heading", { name: "Account" })).toBeInTheDocument();
    expect(screen.getByText("Email is required.")).toHaveAttribute("role", "alert");
    expect(screen.getByText("Password is required.")).toHaveAttribute("role", "alert");
    expect(screen.getByLabelText("Email")).toBeInvalid();

    // Malformed email and a too-short password are also rejected.
    await user.type(screen.getByLabelText("Email"), "not-an-email");
    await user.type(screen.getByLabelText("Password"), "short");
    await user.click(screen.getByRole("button", { name: "Next" }));
    expect(screen.getByText("Enter a valid email address.")).toBeInTheDocument();
    expect(screen.getByText("Password must be at least 8 characters.")).toBeInTheDocument();
    expect(screen.getByRole("heading", { name: "Account" })).toBeInTheDocument();
    expect(onComplete).not.toHaveBeenCalled();

    // Once valid, Next advances to the profile step.
    await user.clear(screen.getByLabelText("Email"));
    await user.type(screen.getByLabelText("Email"), "grace@example.com");
    await user.clear(screen.getByLabelText("Password"));
    await user.type(screen.getByLabelText("Password"), "navy-admiral-42");
    await user.click(screen.getByRole("button", { name: "Next" }));
    expect(screen.getByRole("heading", { name: "Profile" })).toBeInTheDocument();
  });

  it("preserves entered data when navigating back and forth via the confirm screen's Edit links", async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    render(<Wizard onComplete={onComplete} />);

    await fillAccount(user, "alan@example.com", "enigma-1940");
    await user.type(screen.getByLabelText("Display name"), "Alan Turing");
    await user.click(screen.getByRole("button", { name: "Next" }));

    // Jump back to step one from the confirm screen's Edit link.
    await user.click(screen.getByRole("link", { name: "Edit account" }));
    expect(screen.getByRole("heading", { name: "Account" })).toBeInTheDocument();

    // Back navigation never loses data: fields are repopulated.
    expect(screen.getByLabelText("Email")).toHaveValue("alan@example.com");
    expect(screen.getByLabelText("Password")).toHaveValue("enigma-1940");

    // Forward again through profile — display name survives too.
    await user.click(screen.getByRole("button", { name: "Next" }));
    expect(screen.getByLabelText("Display name")).toHaveValue("Alan Turing");
    await user.click(screen.getByRole("button", { name: "Next" }));

    // And the other Edit link works as well.
    await user.click(screen.getByRole("link", { name: "Edit profile" }));
    expect(screen.getByLabelText("Display name")).toHaveValue("Alan Turing");

    // Finish after the round trip; payload still intact.
    await user.click(screen.getByRole("button", { name: "Next" }));
    await user.click(screen.getByRole("button", { name: "Submit" }));
    expect(onComplete).toHaveBeenCalledWith<WizardData>({
      email: "alan@example.com",
      password: "enigma-1940",
      displayName: "Alan Turing",
    });
  });
});
"})
